n secondary small" type="button" data-copy="<?=htmlspecialchars($path,ENT_QUOTES,'UTF-8')?>">Copy path</button><?php if($used):?><span class="admin-media-protected" title="Remove or replace this image in the places listed above before deleting it.">Protected · in use</span><?php else:?><form method="post" data-confirm="Delete this unused media file?" data-confirm-tone="danger"><?=csrf_field()?><input type="hidden" name="action" value="delete"><?=admin_password_field('Confirm media deletion')?><input type="hidden" name="path" value="<?=htmlspecialchars($path,ENT_QUOTES,'UTF-8')?>"><button class="app-button admin-button danger small" type="submit">Delete</button></form><?php endif;?></div></article><?php endforeach;?></div><?php endif;?>
